#!/usr/bin/env python3
"""Writes font.h from Spleen's BDF files: fonts.py <dir with spleen-*.bdf> > font.h"""

import sys
from pathlib import Path

SIZES = [(8, 16), (12, 24), (16, 32)]
# ASCII and Latin-1, the rest is drawn as '?'
CHARS = [*range(32, 127), *range(160, 256)]

LICENSE = """/*
 * Generated by fonts.py from Spleen 2.2.0 (https://github.com/fcambus/spleen).
 *
 * Copyright (c) 2018-2026, Frederic Cambus
 * All rights reserved.
 *
 * Redistribution and use in source and binary forms, with or without
 * modification, are permitted provided that the following conditions are met:
 *
 *   * Redistributions of source code must retain the above copyright
 *     notice, this list of conditions and the following disclaimer.
 *
 *   * Redistributions in binary form must reproduce the above copyright
 *     notice, this list of conditions and the following disclaimer in the
 *     documentation and/or other materials provided with the distribution.
 *
 * THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS"
 * AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE
 * IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE
 * ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDERS OR CONTRIBUTORS BE
 * LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR
 * CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF
 * SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS
 * INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN
 * CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE)
 * ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE
 * POSSIBILITY OF SUCH DAMAGE.
 */
"""


def glyphs(path: Path, height: int) -> dict[int, list[int]]:
    """Each glyph as rows of 16 bits, left-aligned, in a cell of the font's height."""
    found: dict[int, list[int]] = {}
    code = 0
    ascent = height
    box_width = box_height = x_offset = y_offset = 0
    rows: list[str] = []
    in_bitmap = False
    for line in path.read_text().splitlines():
        fields = line.split()
        if not fields:
            continue
        key = fields[0]
        if key == "FONTBOUNDINGBOX":
            ascent = int(fields[2]) + int(fields[4])
        elif key == "ENCODING":
            code = int(fields[1])
        elif key == "BBX":
            box_width, box_height, x_offset, y_offset = map(int, fields[1:5])
        elif key == "BITMAP":
            in_bitmap = True
            rows = []
        elif key == "ENDCHAR":
            cell = [0] * height
            top = ascent - (y_offset + box_height)
            for i, row in enumerate(rows):
                y = top + i
                if 0 <= y < height:
                    bits = int(row, 16) >> (len(row) * 4 - box_width)
                    cell[y] = (bits << (16 - box_width - x_offset)) & 0xFFFF
            found[code] = cell
            in_bitmap = False
        elif in_bitmap:
            rows.append(key)
    return found


def main() -> None:
    source = Path(sys.argv[1])
    print(LICENSE)
    print(f"#define FONT_CHARS {len(CHARS)}")
    for width, height in SIZES:
        font = glyphs(source / f"spleen-{width}x{height}.bdf", height)
        print(f"\nstatic const unsigned short font{width}x{height}[FONT_CHARS][{height}] =\n{{")
        for char in CHARS:
            cell = font.get(char, font[ord("?")])
            print("    {" + ", ".join(f"0x{v:04x}" for v in cell) + "},")
        print("};")


main()
